412		point-consistency estimates that lemma asserts at a parameter $\delta_G \geq 0$,
413		is assumed as data rather than obtained from that lemma. There is a universal
414		constant $C_{\mathrm{ext}} \geq 1$ such that the following holds for every
415		admissible $(q,m,d)$, every $0 \leq \eps \leq 1$, every projective strategy
416		setup at error $\eps$ (Lemma~\ref{lem:projective-strategy-setup}), every
417		$\delta_G \geq 0$, and every assumed measurement as above. The swap unitaries
418		$V_{\mathrm{A}}$ and $V_{\mathrm{B}}$ built from that measurement by
419		Definition~\ref{def:v-swap-unitary} are two-sided unitaries, and there is a
420		normalized state $\ket{\mathrm{aux}}$ on registers
421		$\mathrm{A}\mathrm{A}'\mathrm{B}\mathrm{B}'$ for which items 1 and 2 of
422		Lemma~\ref{lem:qld-unitary} hold at the scale $\delta_{\mathrm{qld}}$ of that
423		lemma, computed from $\eps$ and the assumed $\delta_G$.
424		The assumed measurement is proof debt rather than a faithful boundary
425		hypothesis: Lemma~\ref{lem:qld-unitary} obtains it from
426		Lemma~\ref{lem:qld-4-7} before constructing the swap unitaries. Eliminating
427		the assumption requires carrying out that construction first; this missing
428		composition is recorded in \cite{gap:qpbt_extraction-transfer}.
429		The corresponding proof obligation repeats the argument of
430		Lemma~\ref{lem:qld-unitary} above, using the assumed
431		measurement in place of the appeal to Lemma~\ref{lem:qld-4-7}.
432	\end{remark}
433	
434	\begin{lemma}[Preservation of the robustness error family]\label{lem:qld-extraction-error-form}
435		\lean{MIPStarRE.QPBT.deltaExtract_le_deltaQld}
436		\uses{def:admissible, lem:qld-unitary}
437		Let $C\geq1$, $a>1$, and $0<b<1$. Suppose that
438		\[
439			\delta_G=a(md)^a\bigl(\eps^b+q^{-b}+2^{-bmd}\bigr),
440			\qquad
441			\delta_P=C\left(\delta_G+\sqrt{\eps}+\frac{md}{q}\right),
442		\]
443		and set $\delta_{\mathrm{ext}}=C(\delta_P^{1/4}+md/q)$. There are constants
444		$a'\geq1$ and $0<b'<1$, depending only on $C,a,b$, such that, for every
445		admissible $(q,m,d)$ and every $0\leq\eps\leq1$,
446		\[
447			\delta_{\mathrm{ext}}
448			\leq a'(md)^{a'}\bigl(\eps^{b'}+q^{-b'}+2^{-b'md}\bigr).
449		\]
450	\end{lemma}
451	
452	\begin{remark}[Two steps in the source proof of the extraction lemma]\label{rem:qld-unitary-triangle-slip}
453		In the source proof of Lemma~\ref{lem:qld-unitary}, the triangle inequality gives $\| H_X \ket{\vartheta} - H_Z \ket{\vartheta} \| \leq \| (\Id - H_X)\ket{\vartheta} \| + \| (\Id - H_Z)\ket{\vartheta} \| \leq 2\sqrt{\delta_P}$, so that $\| H_X \ket{\vartheta} - H_Z \ket{\vartheta} \|^2 \leq 4\delta_P$; the source instead asserts the bound $2\sqrt{\delta_P}$ for the \emph{squared} norm, which holds only when $\sqrt{\delta_P} \leq 1/2$, and consequently carries the term $\sqrt{\delta_P}$ into an overlap bound of $1 - 2\delta_P - \sqrt{\delta_P}$. The proof above uses the corrected bound $4\delta_P$, which gives the overlap bound $1 - 4\delta_P$ and leaves the final bound $\delta_{\mathrm{qld}} = O(\delta_P^{1/4} + md/q)$ unchanged. The source proof also normalizes the vector $(\bra{\mathrm{EPR}_q}^{\ot M})_{\mathrm{A}''\mathrm{B}''} \ket{\vartheta}$ without ensuring that it is nonzero; the case distinction on $\delta_P$ in the proof above supplies this, the conclusions of the lemma being trivial when $\delta_P$ exceeds a universal constant.
454		The numerical corrections and their role in the extraction argument are
455		documented in \cite{gap:qpbt_extraction-transfer}.
456	\end{remark}
